import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.util.stream.Collectors;
/** Guarda o estado completo, em arquivo privado do servidor, com substituição atômica. */
public class Repositorio {
    private final BancoPostgres banco = BancoPostgres.configurado();
    public boolean online(){return banco!=null;}
    private final Path arquivo; public Repositorio(Path arquivo){this.arquivo=arquivo;}
    static String seed()throws java.io.IOException{try(java.io.InputStream in=Repositorio.class.getResourceAsStream("/seed.json")){if(in==null)throw new java.io.IOException("Seed indisponível");return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}
    static List<Integer> ids(List<Usuario> us){return us.stream().map(Usuario::getId).collect(Collectors.toList());}
    public void salvar(SistemaEscolar s)throws java.io.IOException{
        List<Object> as=new ArrayList<>(),es=new ArrayList<>(),ps=new ArrayList<>(),ms=new ArrayList<>(),us=new ArrayList<>();
        for(Usuario u:s.getUsuarios())us.add(Json.obj("id",u.getId(),"nome",u.getNome(),"perfil",u.getPerfil().name(),"email",u.email(),"login",u.login(),"senhaHash",u.senhaHash(),"codigo",u.codigo()));
        for(Atividade a:s.todasAtividades()){List<Object> ent=new ArrayList<>();for(Entrega e:a.getEntregas())ent.add(Json.obj("aluno",e.getAluno().getId(),"resposta",e.getResposta(),"data",e.getData().toString()));as.add(Json.obj("id",a.getId(),"titulo",a.getTitulo(),"materia",a.getMateria(),"descricao",a.getDescricao(),"prazo",a.getPrazo().toString(),"professor",a.getProfessor().getId(),"turma",a.getTurma(),"entregas",ent));}
        for(Equipe e:s.todasEquipes())es.add(Json.obj("id",e.getId(),"nome",e.getNome(),"descricao",e.getDescricao(),"foto",e.getFoto(),"lider",e.getLider().getId(),"membros",ids(e.getMembros()),"convites",ids(e.getConvites()),"publica",e.isPublica(),"nomePublico",e.isNomePublico(),"liderPublico",e.isLiderPublico(),"membrosPublicos",e.isMembrosPublicos()));
        for(Projeto p:s.todosProjetos())ps.add(Json.obj("id",p.getId(),"nome",p.getNome(),"descricao",p.getDescricao(),"equipe",p.getEquipe().getId(),"mentor",p.getMentor()==null?null:p.getMentor().getId(),"publico",p.isPublico()));
        for(Mentoria m:s.todasMentorias())ms.add(Json.obj("id",m.getId(),"projeto",m.getProjeto().getId(),"professor",m.getProfessor().getId(),"assunto",m.getAssunto(),"horario",m.getHorario().toString(),"status",m.getStatus().name()));
        String json=Json.stringify(Json.obj("versao",2,"academico",s.academico.salvar(),"codigos",s.codigosInternos(),"usuarios",us,"atividades",as,"equipes",es,"projetos",ps,"mentorias",ms));if(banco!=null){banco.salvar(json);return;}
        Files.createDirectories(arquivo.toAbsolutePath().getParent());Path tmp=arquivo.resolveSibling(arquivo.getFileName()+".tmp");Files.writeString(tmp,json,StandardCharsets.UTF_8);try{Files.move(tmp,arquivo,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException ex){Files.move(tmp,arquivo,StandardCopyOption.REPLACE_EXISTING);}
    }
    public SistemaEscolar carregar()throws java.io.IOException{
        SistemaEscolar s=new SistemaEscolar();String raw;
        if(banco!=null){raw=banco.carregar();}else{if(!Files.exists(arquivo)){Files.createDirectories(arquivo.toAbsolutePath().getParent());Files.writeString(arquivo,seed());}raw=Files.readString(arquivo);}Map<String,Object> root=Json.map(Json.parse(raw));if(Json.num(root,"versao")!=2)throw new IllegalArgumentException("Dados antigos: preserve o JSON da Sprint 4 e use um arquivo novo da Sprint 5.");s.usuariosInternos().clear();for(Object x:Json.list(root.get("usuarios"))){Map<String,Object> m=Json.map(x);Usuario u=new Usuario(Json.num(m,"id"),Json.str(m,"nome"),Usuario.Perfil.valueOf(Json.str(m,"perfil")));u.credenciais(Json.str(m,"email"),Json.str(m,"login"),Json.str(m,"senhaHash"),Json.str(m,"codigo"));s.usuariosInternos().add(u);}for(Object x:Json.list(root.get("codigos")))s.codigosInternos().add((String)x);
        s.academico.carregar(root.get("academico"));
        for(Object x:Json.list(root.get("atividades"))){Map<String,Object> m=Json.map(x);Atividade a=new Atividade(Json.num(m,"id"),Json.str(m,"titulo"),Json.str(m,"materia"),Json.str(m,"descricao"),LocalDate.parse(Json.str(m,"prazo")),s.usuario(Json.num(m,"professor")));if(m.containsKey("turma"))a.definirTurma(Json.num(m,"turma"));for(Object y:Json.list(m.get("entregas"))){Map<String,Object> e=Json.map(y);a.registrar(s.usuario(Json.num(e,"aluno")),Json.str(e,"resposta"),LocalDate.parse(Json.str(e,"data")));}s.todasAtividades().add(a);}
        for(Object x:Json.list(root.get("equipes"))){Map<String,Object> m=Json.map(x);Equipe e=new Equipe(Json.num(m,"id"),Json.str(m,"nome"),Json.str(m,"descricao"),Json.str(m,"foto"),s.usuario(Json.num(m,"lider")));e.privacidade(Json.bool(m,"publica"),Json.bool(m,"nomePublico"),Json.bool(m,"liderPublico"),Json.bool(m,"membrosPublicos"));for(Object y:Json.list(m.get("membros"))){Usuario u=s.usuario(((Number)y).intValue());if(!e.temMembro(u)){e.convidar(u);e.responder(u,true);}}for(Object y:Json.list(m.get("convites")))e.convidar(s.usuario(((Number)y).intValue()));s.todasEquipes().add(e);}
        for(Object x:Json.list(root.get("projetos"))){Map<String,Object> m=Json.map(x);Projeto p=new Projeto(Json.num(m,"id"),Json.str(m,"nome"),Json.str(m,"descricao"),s.equipe(Json.num(m,"equipe")));p.privacidade(Json.bool(m,"publico"));if(m.get("mentor")!=null)p.vincularMentor(s.usuario(Json.num(m,"mentor")));s.todosProjetos().add(p);}
        for(Object x:Json.list(root.get("mentorias"))){Map<String,Object> m=Json.map(x);s.todasMentorias().add(new Mentoria(Json.num(m,"id"),s.projeto(Json.num(m,"projeto")),s.usuario(Json.num(m,"professor")),Json.str(m,"assunto"),LocalDateTime.parse(Json.str(m,"horario")),Mentoria.Status.valueOf(Json.str(m,"status"))));}return s;
    }
}
